'use strict';
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)'),finePointer=matchMedia('(hover: hover) and (pointer: fine)');
const root=document.documentElement;
const reveal=[...document.querySelectorAll('.reveal')];
if('IntersectionObserver' in window&&!reduceMotion.matches){root.classList.add('js');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});reveal.forEach(el=>observer.observe(el));}
const progress=document.querySelector('.progress'),poster=document.querySelector('.identity-poster'),pattern=document.querySelector('.arch-pattern');let scrollFrame=0;
function scrollUpdate(){const max=root.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?Math.min(scrollY/max,1):0})`;if(!reduceMotion.matches){pattern.style.setProperty('--arch-offset',`${Math.min(scrollY*.12,100)}px`);const rect=poster.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight)poster.style.setProperty('--poster-offset',`${(innerHeight/2-rect.top-rect.height/2)*.065-rect.height*.035}px`)}scrollFrame=0;}
addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(scrollUpdate)},{passive:true});addEventListener('resize',scrollUpdate);scrollUpdate();
const cursor=document.getElementById('cursor'),preview=document.getElementById('project-preview');let x=-100,y=-100,targetX=-100,targetY=-100,pointerFrame=0,pointerActive=false,activeProject=null;
function renderPointer(){x+=(targetX-x)*.18;y+=(targetY-y)*.18;cursor.style.transform=`translate(${x}px,${y}px) translate(-50%,-50%)`;preview.style.left=`${Math.max(165,Math.min(innerWidth-165,x))}px`;preview.style.top=`${Math.max(120,Math.min(innerHeight-120,y))}px`;if(pointerActive&&Math.abs(targetX-x)+Math.abs(targetY-y)>.2){pointerFrame=requestAnimationFrame(renderPointer)}else pointerFrame=0;}
function resetPointer(){pointerActive=false;cursor.style.opacity='0';preview.classList.remove('visible');activeProject=null;if(pointerFrame)cancelAnimationFrame(pointerFrame);pointerFrame=0;document.querySelectorAll('.magnetic').forEach(el=>el.style.transform='');}
document.addEventListener('pointermove',e=>{if(!finePointer.matches||reduceMotion.matches)return;pointerActive=true;targetX=e.clientX;targetY=e.clientY;const project=e.target.closest('.project');if(project!==activeProject){activeProject=project;if(project){preview.querySelector('img').src=project.dataset.preview;preview.querySelector('span').textContent=project.dataset.label;preview.classList.add('visible')}else preview.classList.remove('visible')}cursor.style.opacity=project?'0':'1';cursor.classList.toggle('link',!!e.target.closest('a,button'));if(!pointerFrame)pointerFrame=requestAnimationFrame(renderPointer)},{passive:true});
document.documentElement.addEventListener('pointerleave',resetPointer);addEventListener('blur',resetPointer);
document.querySelectorAll('.project').forEach(a=>a.addEventListener('click',resetPointer));
for(const el of document.querySelectorAll('.magnetic')){el.addEventListener('pointermove',e=>{if(!finePointer.matches||reduceMotion.matches)return;const rect=el.getBoundingClientRect();el.style.transition='transform .4s cubic-bezier(.22,1,.36,1)';el.style.transform=`translate(${(e.clientX-rect.left-rect.width/2)*.22}px,${(e.clientY-rect.top-rect.height/2)*.22}px)`});el.addEventListener('pointerleave',()=>{el.style.transition='transform .7s cubic-bezier(.22,1,.36,1)';el.style.transform='translate(0,0)'})}
const menu=document.getElementById('menu'),toggle=document.querySelector('.menu-button');
toggle.addEventListener('click',()=>{menu.showModal();toggle.setAttribute('aria-expanded','true');resetPointer()});
document.querySelector('.menu-close').addEventListener('click',()=>menu.close());menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>menu.close()));menu.addEventListener('close',()=>toggle.setAttribute('aria-expanded','false'));menu.addEventListener('click',e=>{if(e.target!==menu)return;const r=menu.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)menu.close()});
reduceMotion.addEventListener('change',()=>{if(reduceMotion.matches){resetPointer();reveal.forEach(el=>el.classList.add('visible'));poster.style.removeProperty('--poster-offset');pattern.style.removeProperty('--arch-offset')}});
const time=document.getElementById('local-time');function updateTime(){time.textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'}).format(new Date())}updateTime();setInterval(updateTime,60000);document.getElementById('year').textContent=new Date().getFullYear();
let toastTimer;document.getElementById('copy').addEventListener('click',async()=>{const toast=document.getElementById('toast');try{await navigator.clipboard.writeText('13243503433');toast.textContent='电话号码已复制'}catch{toast.textContent='请长按号码复制：13243503433'}toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),2800)});
